@extends('admin.layout') @section('title','Bulk Product Labels') @section('page_heading','Bulk Product Labels') @section('content')<style>.labels{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:20px}.label{border:1px dashed #94a3b8;padding:12px;text-align:center;min-height:190px;background:#fff}.label h3{font-size:12px;margin:4px}.code{font:900 16px monospace;letter-spacing:1px}.price{font-weight:900;font-size:15px}.meta{font-size:9px;color:#64748b}.actions{padding:15px}.actions button{padding:10px 15px;background:#111827;color:#fff;border:0;border-radius:8px}@media print{.actions{display:none}.labels{grid-template-columns:repeat(3,1fr);gap:6px}.label{break-inside:avoid}}@media(max-width:800px){.labels{grid-template-columns:repeat(2,1fr)}} </style><div class="actions"><button onclick="window.print()">Print / Save PDF</button></div><div class="labels">@foreach($products as $p)<div class="label"><div class="meta">CHACHA PRIME</div><h3>{{IlluminateSupportStr::limit($p->name,55)}}</h3><svg class="barcode" data-code="{{$p->barcode_value ?: $p->sku}}"></svg><div class="code">{{$p->product_code}}</div><div class="meta">SKU: {{$p->sku}}</div><div class="price">{{$p->currency}} {{number_format((float)$p->retail_price,2)}}</div><canvas class="qr" data-token="{{route('product',$p->id)}}"></canvas></div>@endforeach</div><script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js"></script><script src="https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js"></script><script>document.querySelectorAll(".barcode").forEach(x=>JsBarcode(x,x.dataset.code,{format:"CODE128",displayValue:false,height:42,width:1.5,margin:3}));document.querySelectorAll(".qr").forEach(x=>new QRCode(x,{text:x.dataset.token,width:75,height:75}));</script>@endsection